<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {Check,ArrowRight,ArrowLeft,LoaderCircle,Trash2,MapPin,AlertTriangle} from '@lucide/vue'
import PlacePicker from './PlacePicker.vue'
import {places,placeById,registerPlaces,uid,time,type Requirements,type Trip,type Place} from '../domain'
import {api} from '../api'
const props=defineProps<{loggedIn:boolean;hasModel:boolean}>()
const emit=defineEmits<{created:[trip:Trip];login:[]}>()
const step=ref(0),intent=ref(''),title=ref('我的杭州慢游'),error=ref(''),busy=ref(false),useModel=ref(props.hasModel)
const req=ref<Requirements>({city:'杭州',startDate:'',days:2,people:2,mode:'walk',start:570,end:1110,pace:'balanced',interests:[],originPlaceId:null,destinationPlaceId:null,returnBy:null})
const candidateIds=ref(['quyuan','museum','louwailou','baidi','hubin','liulang','leifeng','art'])
const draft=ref<{trip:Trip;source:string;issues:{message:string}[];warnings:string[]}|null>(null)
const valid=computed(()=>!!req.value.startDate&&req.value.days>=1&&req.value.days<=3&&req.value.start<req.value.end&&req.value.people>=1&&req.value.people<=10)
const selected=computed(()=>candidateIds.value.map(id=>placeById(id)))
watch(()=>props.hasModel,value=>useModel.value=value)
function minutes(value:string){const [h,m]=value.split(':').map(Number);return h!*60+m!}
function updateTime(event:Event,key:'start'|'end'|'returnBy'){const value=(event.target as HTMLInputElement).value;req.value[key]=value?minutes(value):null as never}
function interpret(){error.value='';const text=intent.value;if(/北京|上海|广州|深圳|成都|苏州|南京/.test(text)){error.value='当前仅支持杭州，请先确认城市。';return}const date=text.match(/\d{4}-\d{2}-\d{2}/)?.[0];if(date)req.value.startDate=date;const day=text.match(/([一二两三123])\s*天/);if(day)req.value.days=({'一':1,'二':2,'两':2,'三':3} as Record<string,number>)[day[1]!]||Number(day[1]);const people=text.match(/([一二两三四五六123456789])\s*(?:个)?人/);if(people)req.value.people=({'一':1,'二':2,'两':2,'三':3,'四':4,'五':5,'六':6} as Record<string,number>)[people[1]!]||Number(people[1]);if(/驾车|自驾|开车/.test(text))req.value.mode='drive';else if(/步行/.test(text))req.value.mode='walk';if(/慢|轻松|不.{0,2}赶/.test(text))req.value.pace='relaxed';req.value.interests=['咖啡','拍照','博物馆','美术','自然','美食'].filter(x=>text.includes(x));if(!req.value.startDate)error.value='已提取可识别条件；请手动选择具体出发日期，避免猜测“周末”。'}
function choose(p:Place){if(candidateIds.value.length>=18){error.value='最多选择 18 个游览地点';return}if(!candidateIds.value.includes(p.id))candidateIds.value.push(p.id)}
function next(){error.value='';if(!valid.value){error.value='请确认具体日期、人数和每日时间范围';return}if(req.value.returnBy!==null&&(!req.value.destinationPlaceId||req.value.returnBy!<req.value.start||req.value.returnBy!>req.value.end-15)){error.value='请确认返程地点和时间，至少预留 15 分钟';return}step.value=1}
async function generate(){if(busy.value)return;if(!props.loggedIn){emit('login');return}busy.value=true;error.value='';draft.value=null;try{const data=await api('/planner/draft','POST',{title:title.value,requirements:req.value,candidateIds:candidateIds.value,useModel:useModel.value});registerPlaces(data.trip.placeSnapshots);draft.value=data;step.value=2}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function save(){if(!draft.value||draft.value.issues.length)return;emit('created',draft.value.trip)}
</script>
<template>
 <div class="trip-builder"><span class="eyebrow">YOUR HANGZHOU JOURNEY STARTS HERE</span><h2>{{['这次，想怎么玩杭州？','选定，真正想去的地方。','看看这份杭州草案。'][step]}}</h2>
 <div class="builder-steps"><span v-for="(label,i) in ['确认需求','选择地点','预览保存']" :key="label" :class="{active:step===i}">{{i+1}} · {{label}}</span></div>
 <template v-if="step===0"><label>出行想法<textarea v-model="intent" rows="2" placeholder="例如：2026-11-14去杭州两天，两个人，想喝咖啡和拍照，不要太赶" maxlength="1000"/></label><button class="button quiet small" @click="interpret">提取条件（规则识别）</button><p class="form-hint">识别结果请逐项确认；未提供的具体日期和地点不会猜测。</p><label>旅行名称<input v-model="title" maxlength="80"/></label><div class="form-row"><label>城市<input value="杭州" readonly/></label><label>出发日期<input type="date" v-model="req.startDate" required/></label></div><div class="form-row"><label>旅行天数<select v-model.number="req.days"><option v-for="n in 3" :key="n" :value="n">{{n}} 天</option></select></label><label>同行人数<input type="number" v-model.number="req.people" min="1" max="10"/></label><label>交通方式<select v-model="req.mode"><option value="walk">步行</option><option value="drive">驾车</option></select></label></div><div class="form-row"><label>每天开始<input type="time" :value="time(req.start)" @change="updateTime($event,'start')"/></label><label>每天结束<input type="time" :value="time(req.end)" @change="updateTime($event,'end')"/></label><label>节奏<select v-model="req.pace"><option value="relaxed">轻松</option><option value="balanced">适中</option><option value="full">充实</option></select></label></div><div class="field-label">兴趣偏好<div class="interest-options"><label v-for="interest in ['咖啡','拍照','博物馆','美术','自然','美食']" :key="interest"><input type="checkbox" :value="interest" v-model="req.interests"/>{{interest}}</label></div></div><div class="form-row"><label>首日起点（可选）<select v-model="req.originPlaceId"><option :value="null">不指定</option><option v-for="p in places" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>末日终点（可选）<select v-model="req.destinationPlaceId"><option :value="null">不指定</option><option v-for="p in places" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div><label v-if="req.destinationPlaceId">末日最晚到达（可选）<input type="time" :value="req.returnBy===null?'':time(req.returnBy!)" @change="updateTime($event,'returnBy')"/></label><p v-if="error" class="form-error">{{error}}</p><button class="button primary full" @click="next">确认需求，选择地点<ArrowRight :size="16"/></button></template>
 <template v-else-if="step===1"><div class="requirements-summary">{{req.startDate}} · {{req.days}} 天 · {{req.people}} 人 · {{req.mode==='walk'?'步行':'驾车'}} · {{time(req.start)}}—{{time(req.end)}}<span>{{req.interests.join(' / ')||'无特别偏好'}}</span></div><div class="candidate-list"><strong>游览候选 · {{candidateIds.length}} 个</strong><p v-for="p in selected" :key="p.id"><MapPin :size="13"/><span>{{p.name}}</span><button @click="candidateIds=candidateIds.filter(id=>id!==p.id)" :aria-label="`移除候选${p.name}`"><Trash2 :size="13"/></button></p></div><p v-if="req.originPlaceId||req.destinationPlaceId" class="form-hint">起终点会独立添加，请从游览候选中移除同一地点。</p><PlacePicker :selected="candidateIds" @choose="choose"/><label class="model-choice"><input type="checkbox" v-model="useModel" :disabled="!hasModel"/>{{hasModel?'使用模型分配日期和顺序':'当前为规则规划，将使用地理邻近草案'}}</label><p class="form-hint">{{useModel?'将把确认的需求和候选地点发给模型，随后程序核验地点和道路用时。':'规则草案使用确认的地点和道路估时，不代表 AI 生成，也不保证全局最优。'}}</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-actions"><button class="button quiet" @click="step=0" :disabled="busy"><ArrowLeft :size="15"/>修改需求</button><button class="button primary" @click="generate" :disabled="busy||candidateIds.length<req.days"><LoaderCircle v-if="busy" class="spin" :size="15"/>{{busy?'生成并核验道路…':loggedIn?'生成草案':'先登录再生成'}}</button></div></template>
 <template v-else-if="draft"><p class="draft-source">{{draft.source==='model'?'模型生成 · 程序已校验道路':'规则草案 · 已校验道路用时'}}</p><section v-for="(day,i) in draft.trip.days" :key="day.date" class="draft-day"><h3>Day {{i+1}} · {{day.date}}</h3><p v-for="a in day.activities" :key="a.id"><span>{{placeById(a.placeId).name}}</span><small>{{a.duration}} 分钟{{a.lock==='fixed'?' · 固定到达 '+time(a.fixedStart!):''}}</small></p></section><p v-for="issue in draft.issues" :key="issue.message" class="form-error"><AlertTriangle :size="13"/>{{issue.message}}</p><p v-for="warning in draft.warnings" :key="warning" class="form-hint">{{warning}}</p><div class="modal-actions"><button class="button quiet" @click="step=1">返回调整</button><button class="button primary" @click="save" :disabled="draft.issues.length>0"><Check :size="16"/>确认并保存旅行</button></div><p v-if="draft.issues.length" class="form-hint">存在冲突时不会保存，请调整每日时间、候选地点或交通方式后重新生成。</p></template>
 </div>
</template>
